import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, texture, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, PlaneGeometry, Mesh, DoubleSide } = THREE;

  const palette = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Features 3' };
  const labelText = (headline.text ?? 'Features 3').toString();

  const root = new Group();
  root.name = 'hub-features-card-3-label';

  // --- aspect ratio from atlas source rect (512x320) ---
  const aspect = 512 / 320;
  const planeHeight = 0.42;
  const planeWidth = planeHeight * aspect;

  // --- engineered gradient plaque (ink -> surface) with grain multiply + accent underline ---
  const uvNode = uv();
  const inkColor = color(palette.ink);
  const surfaceColor = color(palette.surface);
  const accentColor = color(palette.accent);

  const gradient = mix(surfaceColor, inkColor, uvNode.y);

  // thin accent underline strip near bottom edge (<=10% of plaque area)
  const underlineMask = smoothstep(0.0, 0.05, uvNode.y).oneMinus().mul(smoothstep(-0.02, 0.0, uvNode.y));
  const withUnderline = mix(gradient, accentColor, underlineMask.mul(0.9));

  const plaqueMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  plaqueMat.colorNode = withUnderline;

  const plaqueGeo = new PlaneGeometry(planeWidth, planeHeight, 1, 1);
  const plaqueMesh = new Mesh(plaqueGeo, plaqueMat);
  plaqueMesh.position.z = 0;
  root.add(plaqueMesh);

  // --- grain texture, loaded async, then folded into the color node ---
  let grainTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      grainTexture = tex;
      grainTexture.wrapS = THREE.RepeatWrapping;
      grainTexture.wrapT = THREE.RepeatWrapping;
      const grainNode = texture(grainTexture, uvNode);
      const grained = withUnderline.mul(mix(color('#ffffff'), grainNode, 0.12));
      plaqueMat.colorNode = grained;
      plaqueMat.needsUpdate = true;
    }).catch(() => {});
  }

  // --- text: label copy, mono, small caption-scale, ASCII only ---
  const textObj = ctx.fontAtlas.createText(labelText.toUpperCase(), {
    fontSize: 39,
    color: palette.paper,
    align: 'center',
    letterSpacingPx: 2.2,
  });
  textObj.position.set(0, 0.02, 0.005);
  const textScale = planeWidth * 0.72 / Math.max(labelText.length * 0.09, 0.4);
  textObj.scale.setScalar(Math.min(0.011 * planeHeight * 12, 0.14));
  root.add(textObj);

  // --- billboard toward camera every frame ---
  root.onBeforeRender = (renderer, scene, camera) => {
    root.quaternion.copy(camera.quaternion);
  };

  // --- weighted-settle entrance (no primitives specified for this node) ---
  root.scale.setScalar(0.97);
  const tl = gsap.timeline();
  tl.to(root.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  });
  tl.fromTo(
    root.position,
    { y: root.position.y - 0.1 },
    { y: root.position.y, duration: 0.7, ease: 'power3.out' },
    0
  );

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    plaqueGeo.dispose();
    plaqueMat.dispose();
    if (grainTexture) grainTexture.dispose?.();
    if (textObj?.geometry) textObj.geometry.dispose?.();
    if (textObj?.material) textObj.material.dispose?.();
    root.onBeforeRender = () => {};
  };

  return root;
}
